The rule: within a mixed row, the minority-colored segment becomes 1; the majority color stays; uniform rows unchanged.

```python
def transform(grid):
    from collections import Counter
    out = [row[:] for row in grid]
    for i, row in enumerate(out):
        cnt = Counter(row)
        if len(cnt) == 2:
            colors = sorted(cnt, key=lambda c: cnt[c])
            if cnt[colors[0]] < cnt[colors[1]]:
                minority = colors[0]
                for j, c in enumerate(row):
                    if c == minority:
                        row[j] = 1
    return out
